import assert from 'node:assert/strict';
import { spawn, execFileSync } from 'node:child_process';
import { mkdir, mkdtemp, writeFile, readFile, open } from 'node:fs/promises';
import path from 'node:path';
import { NectarService } from '../../dist/service.js';
import { daemonHello, callDaemon } from '../../dist/control.js';
import { pidAlive } from '../../dist/commands.js';
import { portOpen } from '../../dist/ports.js';
import { serveEntries, serveStatus } from '../../dist/tailscale.js';
import { probeProxy } from '../../dist/proxy.js';
const root = path.resolve(process.argv[2] ?? `test/fixtures/.runs/lru-${Date.now()}`);
await mkdir(root, {recursive:true});
const state = path.join(root,'state');
process.env.NECTAR_HOME=state;
process.env.NECTAR_SOCKET=path.join(await mkdtemp('/tmp/nectar-t12-'),'control.sock');
process.env.NECTAR_TEST_RUNTIME_MEMORY_BYTES=String(15*256*1024**2);
const service = new NectarService(state);
await service.store.init();
await service.store.writeConfig({...await service.store.readConfig(),upstream_port_start:22100,upstream_port_end:22599,tailnet_port_start:22600,tailnet_port_end:22799,pack_server_port:22099,idle_stop_ms:3600000});
const repo=path.join(root,'repo');await mkdir(repo);
const git=(...args)=>execFileSync('git',args,{cwd:repo,stdio:'pipe'});
git('init','-b','main');git('config','user.email','fixture@example.invalid');git('config','user.name','Fixture');
await writeFile(path.join(repo,'nectar.toml'),'name = "t12-lru"\n[web]\nserve = "exec node server.mjs"\nready_timeout = "5s"\n');
await writeFile(path.join(repo,'server.mjs'),'import http from "node:http";import {existsSync} from "node:fs";const server=http.createServer((req,res)=>{res.writeHead(200);res.write("awake:"+process.env.NECTAR_ENV+":"+process.pid);if(req.url!=="/stream")res.end();});setTimeout(()=>server.listen(Number(process.env.PORT),"127.0.0.1"),existsSync(".slow-ready")?2500:0);');
git('add','.');git('commit','-m','LRU fixture');
const log=await open(path.join(root,'daemon.log'),'a');let daemon;
const wait=ms=>new Promise(r=>setTimeout(r,ms));
const until=async fn=>{const end=Date.now()+20000;while(!await fn()){assert(Date.now()<end,'timeout');await wait(50);}};
const say=x=>console.log(JSON.stringify({at:new Date().toISOString(),...x}));
const call=(command,args={})=>callDaemon(process.env.NECTAR_SOCKET,command,{nectar_home:state,caller:{},args});
const records=[],pids=new Set(),views=new Map();let controller;
const start=async()=>{daemon=spawn(process.execPath,['dist/cli.js','daemon','run','--interval','500ms','--gc-interval','1h'],{env:process.env,stdio:['ignore',log.fd,log.fd]});await until(async()=>{try{return(await daemonHello(process.env.NECTAR_SOCKET)).pid===daemon.pid;}catch{return false;}});say({daemon:daemon.pid,state});};
const halt=async()=>{daemon.kill('SIGTERM');await new Promise(r=>daemon.once('exit',r));};
const publish=async n=>{const branch=`p${String(n).padStart(2,'0')}`;git('branch',branch);const r=await call('publish',{path:repo,branch,mode:'web',local:true});assert.equal(r.via,'nectard');assert.match(r.preview_url,/^https:/);records.push(r);say({publish:r.env,url:r.preview_url,slept:r.slept_previews});return r;};
const visit=async(r,expected)=>{views.set(r.env,Date.now());const response=execFileSync('curl',['--fail','-isS','--max-time','25',r.preview_url],{encoding:'utf8'});assert(response.includes(`awake:${r.env}:`),response);pids.add(Number(response.split(':').at(-1)));const victim=/x-nectar-slept-previews: ([^\r\n]+)/i.exec(response)?.[1];say({view:r.env,victim:victim??null,url:r.preview_url});if(expected!==undefined)assert.equal(victim,expected);await wait(30);return response;};
const capacityText=async()=>{let text='';for(const suffix of ['.2','.1',''])text+=await readFile(path.join(state,'capacity.jsonl'+suffix),'utf8').catch(()=> '');return text;};
const events=async()=>{const text=await capacityText();return text.trim()?text.trim().split('\n').map(x=>JSON.parse(x)).filter(e=>e.event==='capacity_recovery'):[];};
const lastDecision=async(expected)=>{const e=(await events()).at(-1);assert(e,'missing recovery log');assert.equal(e.candidates.find(c=>c.decision==='slept')?.env,expected);for(const c of e.candidates){if(c.env===expected)break;assert(c.skip_reason,`older candidate ${c.env} unexplained`);}say({checkedDecision:e});return e;};
try {
 await start();
 for(let n=1;n<=15;n++)await visit(await publish(n));
 await service.store.writeConfig({...await service.store.readConfig(),idle_stop_ms:2000});
 await until(async()=>(await service.store.listEnvs()).every(r=>r.status==='warm'));
 await halt();await service.store.writeConfig({...await service.store.readConfig(),idle_stop_ms:3600000});await start();
 for(const r of records)await visit(r);
 await halt();
 const reboot=await service.store.readEnv(records[14].env);
 process.kill(reboot.serve.pid,'SIGTERM');await until(async()=>!pidAlive(reboot.serve.pid));
 await writeFile(path.join(reboot.worktree,'.slow-ready'),'delay readiness');
 await service.store.updateEnv(reboot.name,r=>{r.serve.started_at='1970-01-01T00:00:00.000Z';});
 await start();
 assert(!await portOpen(reboot.serve.upstream_port),'control waited for app boot');
 say({rebootRestoration:'control ready before delayed app boot',env:reboot.name});
 await until(async()=>(await readFile(path.join(service.paths.logs,'nectard.log'),'utf8')).split('\n').filter(Boolean).some(line=>{const e=JSON.parse(line);return e.event==='revived'&&e.env===reboot.name&&e.cause==='restore_after_boot';}));
 const routes=serveEntries(await serveStatus());
 for(const r of await service.store.listEnvs())assert.equal(routes.find(e=>e.tailnetPort===r.serve.tailnet_port)?.target,`http://127.0.0.1:${r.serve.proxy_port}`);
 say({routes:await Promise.all((await service.store.listEnvs()).map(async r=>({env:r.name,proxy:r.serve.proxy_port,route:routes.find(e=>e.tailnetPort===r.serve.tailnet_port)?.target,probe:await probeProxy(r.serve.proxy_port,r.name)})))});
 for(const r of records)await visit(r);
 const initialViews=new Map(views);
 const extra=await publish(16);
 await visit(extra,records[0].env);await lastDecision(records[0].env);
 await visit(records[0],records[1].env);await lastDecision(records[1].env);
 await visit(records[1],records[2].env);await lastDecision(records[2].env);
 const first=(await events())[0];for(const r of records.slice(0,15))assert(Date.parse(first.candidates.find(c=>c.env===r.env).last_viewed_at)>=initialViews.get(r.env),`untracked URL visit ${r.env}`);
 say({phase:'ordered-wakes-passed'});
 await visit(records[3]);
 await visit(records[2],records[4].env);
 const refreshed=await lastDecision(records[4].env);
 const recent=refreshed.candidates.find(c=>c.env===records[3].env);
 assert.equal(recent.view_source,'live');
 assert(Date.parse(recent.last_viewed_at)>Date.parse(recent.persisted_last_viewed_at));
 const probeRecord=await service.store.readEnv(records[5].env);
 const saved=probeRecord.last_viewed_at;
 for(let n=0;n<3;n++)assert.equal(await probeProxy(probeRecord.serve.proxy_port,probeRecord.name),probeRecord.serve.upstream_port);
 await service.wakeWeb(probeRecord.name);
 assert.equal((await service.store.readEnv(probeRecord.name)).last_viewed_at,saved);
 await service.store.updateEnv(records[5].env,r=>{r.pinned=true;});
 controller=new AbortController();
 const stream=await fetch(records[6].preview_url+'/stream',{signal:controller.signal});assert.equal(stream.status,200);
 let release;
 const held=new Promise(resolve=>{release=resolve;});
 let acquired;
 const locked=new Promise(resolve=>{acquired=resolve;});
 const holding=service.store.withLock(records[7].env,async()=>{acquired();await held;});
 await locked;
 try {
  await visit(records[4],records[8].env);
  const decision=await lastDecision(records[8].env);
  for(const [index,reason] of [[5,'pinned'],[6,'active_request'],[7,'lock_held']])assert.equal(decision.candidates.find(c=>c.env===records[index].env).skip_reason,reason);
  assert.equal(decision.candidates.find(c=>c.env===records[5].env).last_viewed_at,refreshed.candidates.find(c=>c.env===records[5].env).last_viewed_at);
 } finally {release();await holding;}
 for(const [number,victim,nextVictim] of [[17,7,9],[18,10,11]]) {
  const occupied=(await service.store.readEnv(records[victim].env)).serve.upstream_port;assert(occupied);
  await service.store.writeConfig({...await service.store.readConfig(),upstream_port_start:occupied,upstream_port_end:occupied});
  const result=await publish(number);assert.deepEqual(result.slept_previews,[records[victim].env]);
  const decision=await lastDecision(records[victim].env);assert.equal(decision.code,'E_PORTS');
  await service.store.writeConfig({...await service.store.readConfig(),upstream_port_start:22100,upstream_port_end:22599});
  await visit(result);
  await visit(records[victim],records[nextVictim].env);await lastDecision(records[nextVictim].env);
 }
 controller.abort();controller=undefined;
 for(const r of await service.store.listEnvs())await service.store.updateEnv(r.name,current=>{current.pinned=true;});
 const occupied=(await service.store.readEnv(records[0].env)).serve.proxy_port;
 await service.store.writeConfig({...await service.store.readConfig(),upstream_port_start:occupied,upstream_port_end:occupied,log_max_bytes:1024});
 let refusal;try{await publish(19);}catch(error){refusal=error;}
 assert.equal(refusal?.code,'E_PORTS');
 const refused=(await events()).at(-1);assert(!refused.candidates.some(c=>c.decision==='slept'));assert(refused.candidates.every(c=>c.skip_reason!==null));
 say({noEligible:refusal.message,decision:refused});
 let secondRefusal;try{await publish(20);}catch(error){secondRefusal=error;}
 assert.equal(secondRefusal?.code,'E_PORTS');
 assert((await readFile(path.join(state,'capacity.jsonl.1'),'utf8')).includes('capacity_recovery'));
 assert((await readFile(path.join(state,'capacity.jsonl.2'),'utf8')).includes('capacity_recovery'));
 say({rotation:'capacity.jsonl plus two previous files retained',maxBytes:1024});
 say({PASS:true,checks:'15-preview restart, repeated memory and publish pressure, live throttle, probes, wake, pinned, stream, lock, refusal, log rotation, delayed reboot restoration'});
} finally {
 controller?.abort();
 const final=await service.store.listEnvs();for(const r of final)if(r.serve?.pid>1)pids.add(r.serve.pid);
 await writeFile(path.join(root,'capacity.jsonl'),await capacityText());
 for(const r of final)await service.stop(r.name).catch(()=>{});
 if(daemon.exitCode===null)await halt();await log.close();
 assert.deepEqual(serveEntries(await serveStatus()).filter(e=>final.some(r=>r.serve?.tailnet_port===e.tailnetPort)),[]);
 assert([...pids].every(pid=>!pidAlive(pid)));
 say({cleanup:'own previews and daemon stopped',pidsGone:pids.size,root});
}
